def transform(A, B):
    if len(A) != len(B):
        return -1
    if A == B:
        return 0
    i = j = 0
    steps = 0
    while i < len(A) and j < len(B):
        if A[i] == B[j]:
            i += 1
            j += 1
        else:
            steps += 1
